mapper.select:
select node_id as deviceId,node_type as deviceType,case when warning_type = '01' then '设备电量低' when warning_type = '02' then '设备信号强度差' when warning_type = '03' then '设备丢包' end as repairReason
from tb_early_warning where is_affirm = '2' and warning_type in ('01','02','03')
and area_id = #{areaId}
and stack_id = #{stackId}

mapper.update:
UPDATE tb_early_warning
SET is_affirm = #{affirm},principal = #{principal},deal_time = STR_TO_DATE(#{dealTime}, '%Y-%m-%d %H:%i:%s')
WHERE task_id = #{taskId}

mapper.select:
select id,warning_grade warningGrade,warning_type warningType,is_affirm affirm,node_id nodeId from tb_early_warning where node_id like concat('%',concat(#{nodeId},'%')) and is_affirm in (1,2) 
 and warning_type =#{warningType}

LIMIT 1

select id AS `id`,warning_type AS `warningType` from tb_early_warning where is_affirm in ('1','2')
and warning_type in ('01','02','03') and warning_type = #{earlyWarningDto.warningType}
 and principal = #{earlyWarningDto.principalName} 
 and warning_time >= #{earlyWarningDto.startTime}
 and warning_time <= #{earlyWarningDto.endTime}

SELECT id AS id,area_id AS areaId,stack_id AS stackId,is_affirm AS affirm,node_type AS nodeType,
warning_grade as warningGrade,site_route as siteRoute,warning_time AS warningTime,'01' as warningType,'设备故障' as warningNews,
case when is_affirm = '1' then '正在处理' when is_affirm = '2' then '未处理' end as affirmName
FROM tb_early_warning where id in (SELECT max(id) from tb_early_warning where is_affirm = '2' and warning_type in ('01','02','03')
 and principal = #{earlyWarningDto.principalName} 
 and warning_time >= #{earlyWarningDto.startTime}
 and warning_time <= #{earlyWarningDto.endTime}
group by site_route,node_type) ORDER BY is_affirm DESC

SELECT id AS id, area_id AS areaId, stack_id AS stackId, is_affirm AS affirm,warning_type AS warningType,node_type AS nodeType,
site_route as siteRoute,warning_time AS warningTime,warning_type as warningType,
 AS warningGrade,
 AS warningVal,
case when is_affirm = '1' then '正在处理' when is_affirm = '2' then '未处理' end as affirmName
FROM tb_early_warning where is_affirm in ('01','02')
and warning_type = #{earlyWarningDto.warningType}
 and principal = #{earlyWarningDto.principalName} 
 and warning_time >= #{earlyWarningDto.startTime}
 and warning_time <= #{earlyWarningDto.endTime}
ORDER BY is_affirm DESC

mapper.sql:
WHERE t.is_affirm IN ('1','2')
AND t.node_id LIKE concat(concat('%',#{earlyWarningDto.nodeId}),'%')
AND t.warning_type = #{earlyWarningDto.warningType}
AND  = #{earlyWarningDto.warningGrade}
AND t.principal LIKE concat(concat('%',#{earlyWarningDto.principalName}),'%')
AND t.site_route LIKE concat(concat('%',#{earlyWarningDto.pidRoute}),'%')

mapper.select:
SELECT id AS `id`,site_route AS `pidRoute`,node_id AS `nodeId`,node_type AS `nodeType`,warning_type AS `warningType`,
warning_val AS `warningVal`,stack_id AS `stackId`,area_id AS `areaId` FROM tb_early_warning
WHERE is_affirm = #{affirm} and site_route = #{siteRoute} AND node_type = #{nodeType}
and warning_type in ('01','02','03') and warning_type = #{warningType}

SELECT
t.id AS `id`,t.site_route AS `pidRoute`,t.node_id AS `nodeId`,t.warning_grade AS `warningGrade`,t.node_type AS `nodeType`,t.warning_type AS `warningType`,
t.warning_val AS `warningVal`,t2.site_x AS `siteX`,t2.site_y AS `siteY`,
t2.site_z AS `siteZ` FROM tb_early_warning t left JOIN tb_node t2  ON t.node_id =t2.node_id WHERE warning_type = #{warningType}
AND is_affirm = #{affirm} and t.site_route = #{siteRoute}

SELECT count(is_affirm) AS `sum`,COALESCE(count(IF(CAST(is_affirm AS CHAR) = '0', 1, NULL)),0) AS `deal`,count(is_affirm) - COALESCE(count(IF(CAST(is_affirm AS CHAR) = '0', 1, NULL)),0) AS `noDeal`,
round(COALESCE(count(IF(CAST(is_affirm AS CHAR) = '0', 1, NULL)),0)/count(is_affirm),2) AS `treatmentRate`,
${dateType} AS `day`
FROM tb_early_warning
WHERE 1=1 and id in  #{id}
GROUP BY ${dateType}
ORDER BY ${dateType}

SELECT count(1) AS `sumDeal`,round(COUNT(1)/#{count},2) * 100 AS `ratioDeal`
FROM tb_early_warning
WHERE is_affirm = '0' and id in  #{id}

select warning_type AS `warningType`,node_id AS `nodeId`,
 AS `warningVal`
from tb_early_warning where is_affirm = '2' and id in  #{id}

select COALESCE(count(1),0) from tb_early_warning where is_affirm in('1','2')
and warning_type in ('01','02','03') and warning_type = #{warningType}
and  = #{warningGrade}
GROUP BY warning_type

select id AS `id`,node_type AS `nodeType`,area_id AS `areaId`,stack_id AS `stackId`,principal AS `principal`,site_route AS `siteRoute`,warning_grade AS `grade`,node_id AS `nodeId`,warning_type AS `warningType`,
 AS `warningGrade`,
DATE_FORMAT(, '%Y-%m-%d %H:%i:%s') AS `warningVal`,
DATE_FORMAT(, '%Y-%m-%d %H:%i:%s') AS `warningTime`
from tb_early_warning where is_affirm in('1','2') and warning_type = #{warningType}
and  = #{warningGrade}

select setting_value from tb_general_setting
where setting_key = #{settingKey} and setting_name = #{settingName}
limit 1
